1: import { OpenCode } from "@opencode/client";
2: import {
3:   SUPPORTED_OPENCODE_MAJOR,
4:   TESTED_OPENCODE_VERSION,
5:   type OpenCodeConnectionState,
6: } from "../../shared/opencode.ts";
7: import { nativeEngineStatusSchema, type NativeEngineStatus } from "../../shared/contracts.ts";
8: import {
9:   assertAllowedUrl,
10:   createSafeFetch,
11:   NetworkPolicyError,
12:   sanitizeNetworkError,
13:   validateBaseUrlSyntax,
14:   type NetworkPolicy,
15: } from "../security/network.ts";
16: import { redactText } from "../security/redaction.ts";
17: 
18: export const FREE_DEEPSEEK_MODEL = "opencode/deepseek-v4.1-flash-free" as const;
19: export const REQUIRED_OPENCODE_MAJOR = SUPPORTED_OPENCODE_MAJOR;
