21: export interface NativeClientOptions {
22:   baseUrl: string;
23:   username?: string;
24:   password?: string;
25:   mode?: "local" | "hosted-demo" | "private-hosted";
26:   allowInsecureRemote?: boolean;
27:   allowedHosts?: string[];
28:   allowedPorts?: number[];
29:   allowPrivateNetwork?: boolean;
30:   requestTimeoutMs?: number;
31:   maxResponseBytes?: number;
32:   resolver?: NetworkPolicy["resolver"];
33:   fetchImpl?: typeof fetch;
34: }
35: 
36: export interface NativeEngineError extends Error {
37:   code: "ENGINE_UNAVAILABLE" | "ENGINE_INCOMPATIBLE" | "ENGINE_AUTH" | "MODEL_UNAVAILABLE";
38:   retryable: boolean;
39: }
40: 
41: export function engineError(code: NativeEngineError["code"], message: string, retryable: boolean): NativeEngineError {
42:   const error = new Error(redactText(message)) as NativeEngineError;
43:   error.name = "NativeEngineError";
44:   error.code = code;
45:   error.retryable = retryable;
46:   return error;
47: }
