49: export function networkPolicy(options: NativeClientOptions): NetworkPolicy {
50:   return {
51:     baseUrl: options.baseUrl,
52:     allowInsecureRemote: options.allowInsecureRemote,
53:     allowedHosts: options.allowedHosts,
54:     allowedPorts: options.allowedPorts,
55:     allowPrivateNetwork: options.allowPrivateNetwork,
56:     requestTimeoutMs: options.requestTimeoutMs,
57:     maxResponseBytes: options.maxResponseBytes,
58:     resolver: options.resolver,
59:     fetchImpl: options.fetchImpl,
60:   };
61: }
62: 
63: export function createNativeClient(options: NativeClientOptions) {
64:   const url = validateBaseUrlSyntax(options.baseUrl);
65:   const authorization = options.password
66:     ? `Basic ${Buffer.from(`${options.username || "opencode"}:${options.password}`).toString("base64")}`
67:     : undefined;
68: 
69:   return OpenCode.make({
70:     baseUrl: url.toString(),
71:     fetch: createSafeFetch(networkPolicy(options)),
72:     headers: authorization ? { authorization } : undefined,
73:   });
74: }
75: 
76: export class ConnectionConfigError extends Error {
77:   constructor(
78:     message: string,
79:     readonly code: "INVALID_URL" | "REMOTE_HTTP_FORBIDDEN" | "URL_CREDENTIALS_FORBIDDEN" | "UNSUPPORTED_SCHEME",
80:   ) {
81:     super(message);
82:   }
83: }
84: 
85: export interface ValidatedServerUrl {
86:   url: string;
87:   loopback: boolean;
88:   https: boolean;
89: }
90: 
91: /**
92:  * Validates the OpenCode server address accepted by this application.
93:  *
94:  * Local deployments may use loopback HTTP because the connection never leaves
95:  * the machine. Any non-loopback address must use HTTPS; the network policy
96:  * additionally requires an explicit host allowlist and blocks private and
97:  * metadata addresses unless separately configured.
98:  */
99: export function validateServerUrl(raw: string): ValidatedServerUrl {
100:   const input = raw.trim();
101:   if (!input) throw new ConnectionConfigError("Enter an OpenCode server URL.", "INVALID_URL");
102:   let parsed: URL;
103:   try {
104:     parsed = new URL(input);
105:   } catch {
106:     throw new ConnectionConfigError("The OpenCode server URL is not a valid absolute URL.", "INVALID_URL");
107:   }
108:   if (parsed.protocol !== "http:" && parsed.protocol !== "https:") {
109:     throw new ConnectionConfigError("Only http:// (loopback) and https:// OpenCode URLs are supported.", "UNSUPPORTED_SCHEME");
110:   }
111:   if (parsed.username || parsed.password) {
112:     throw new ConnectionConfigError("Do not put credentials in the server URL. Enter the OpenCode password separately.", "URL_CREDENTIALS_FORBIDDEN");
113:   }
114:   if (parsed.search || parsed.hash) {
115:     throw new ConnectionConfigError("The OpenCode server URL must not include a query string or fragment.", "INVALID_URL");
116:   }
117:   const hostname = parsed.hostname.replace(/^\[|\]$/g, "").toLowerCase();
118:   const loopback = hostname === "localhost" || hostname === "127.0.0.1" || hostname === "::1" || hostname.startsWith("127.");
119:   if (parsed.protocol === "http:" && !loopback) {
120:     throw new ConnectionConfigError("A non-loopback OpenCode URL requires HTTPS.", "REMOTE_HTTP_FORBIDDEN");
121:   }
122:   parsed.pathname = parsed.pathname.replace(/\/+$/, "");
123:   return { url: parsed.toString().replace(/\/$/, ""), loopback, https: parsed.protocol === "https:" };
124: }
125: 
126: export interface VersionCompatibility {
127:   compatible: boolean;
128:   major: number | null;
129:   warning: string | null;
130: }
131: 
132: export function checkVersionCompatibility(version: string): VersionCompatibility {
133:   const match = /^(\d+)\.(\d+)\.(\d+)/.exec(version.trim());
134:   if (!match) {
135:     return { compatible: false, major: null, warning: "The server did not report a parseable semantic version." };
136:   }
137:   const major = Number(match[1]);
138:   if (major !== SUPPORTED_OPENCODE_MAJOR) {
139:     return {
140:       compatible: false,
141:       major,
142:       warning: `OpenCode server ${version} is outside the tested major version ${SUPPORTED_OPENCODE_MAJOR}.`,
143:     };
144:   }
145:   if (version.trim() !== TESTED_OPENCODE_VERSION) {
146:     return {
147:       compatible: true,
148:       major,
149:       warning: `OpenCode server ${version} is a ${SUPPORTED_OPENCODE_MAJOR}.x release, but this build is tested against ${TESTED_OPENCODE_VERSION}. Some capability probes may be unavailable.`,
150:     };
151:   }
152:   return { compatible: true, major, warning: null };
153: }
154: 
155: export interface ClassifiedFailure {
156:   code:
157:     | "AUTH_REQUIRED"
158:     | "ORIGIN_BLOCKED"
159:     | "UNAVAILABLE"
160:     | "TIMEOUT"
161:     | "MALFORMED"
162:     | "VERSION_INCOMPATIBLE"
163:     | "UNKNOWN";
164:   status: number | null;
165:   message: string;
166:   state: OpenCodeConnectionState;
167: }
168: 
169: function errorStatus(error: unknown): number | null {
170:   if (!error || typeof error !== "object") return null;
171:   const candidate = error as { cause?: unknown; status?: unknown; detail?: unknown };
172:   if (typeof candidate.status === "number") return candidate.status;
173:   if (candidate.cause && typeof candidate.cause === "object") {
174:     const nested = candidate.cause as { status?: unknown };
175:     if (typeof nested.status === "number") return nested.status;
176:   }
177:   if (typeof candidate.detail === "string" && /^\d{3}$/.test(candidate.detail)) return Number(candidate.detail);
178:   return null;
179: }
180: 
181: function errorTag(error: unknown): string | null {
182:   return error && typeof error === "object" && typeof (error as { _tag?: unknown })._tag === "string"
183:     ? (error as { _tag: string })._tag
184:     : null;
185: }
186: 
187: function errorMessage(error: unknown): string {
188:   if (error instanceof Error) return error.message;
189:   if (error && typeof error === "object" && typeof (error as { message?: unknown }).message === "string") {
190:     return (error as { message: string }).message;
191:   }
192:   return String(error);
193: }
194: 
195: export function classifyConnectionError(error: unknown): ClassifiedFailure {
196:   const status = errorStatus(error);
197:   const tag = errorTag(error);
198:   const raw = errorMessage(error);
199:   const message = redactSecrets(raw);
200: 
201:   if (status === 401 || tag === "UnauthorizedError" || /authentication required|unauthori[sz]ed|password/i.test(message)) {
202:     return { code: "AUTH_REQUIRED", status: status ?? 401, message, state: "authentication_required" };
203:   }
204:   if (status === 403 || /origin|cors|forbidden|not allowed/i.test(message)) {
205:     return { code: "ORIGIN_BLOCKED", status: status ?? 403, message, state: "unavailable" };
206:   }
207:   if (/ECONNREFUSED|ENOTFOUND|EAI_AGAIN|fetch failed|network|socket|connect/i.test(message)) {
208:     return { code: "UNAVAILABLE", status, message, state: "unavailable" };
209:   }
210:   if (/timed out|timeout|aborted|AbortError/i.test(message)) {
211:     return { code: "TIMEOUT", status, message, state: "unavailable" };
212:   }
213:   if (/malformed|unexpected content|parse|decode/i.test(message)) {
214:     return { code: "MALFORMED", status, message, state: "unavailable" };
215:   }
216:   return { code: "UNKNOWN", status, message, state: "unavailable" };
217: }
218: 
219: const secretPatterns: Array<[RegExp, string]> = [
220:   [/(authorization\s*[:=]\s*)(basic|bearer)?\s*[^\s,;]+/gi, "$1[redacted]"],
221:   [/((?:password|api[_-]?key|access[_-]?token|secret|OPENCODE_PASSWORD|OPENCODE_API_KEY)\s*[:=]\s*)[^\s,;]+/gi, "$1[redacted]"],
222:   [/(https?:\/\/)([^/@\s]+)@/gi, "$1[redacted]@"],
223:   [/(Basic|Bearer)\s+[A-Za-z0-9+/=._-]{8,}/g, "$1 [redacted]"],
224: ];
225: 
226: /** Removes credential-shaped values from anything that may be logged or returned. */
227: export function redactSecrets(value: string): string {
228:   let redacted = value;
229:   for (const [pattern, replacement] of secretPatterns) redacted = redacted.replace(pattern, replacement);
230:   return redacted;
231: }
232: 
233: export async function probeNativeEngine(options: NativeClientOptions): Promise<NativeEngineStatus> {
234:   const mode = options.mode ?? "local";
235:   try {
236:     const url = validateBaseUrlSyntax(options.baseUrl);
237:     await assertAllowedUrl(url, networkPolicy(options));
238:     const client = createNativeClient(options);
239:     const [server, models] = await Promise.all([
240:       client.server.info(),
241:       client.model.list(),
242:     ]);
243:     const versionCompatible = new RegExp(`^${REQUIRED_OPENCODE_MAJOR}\\.`).test(server.version);
244:     const reportedModel = models.data.find((model) => model.enabled !== false) ?? null;
245:     const modelAvailable = reportedModel !== null;
246: 
247:     return nativeEngineStatusSchema.parse({
248:       available: true,
249:       serverVersion: server.version,
250:       versionCompatible,
251:       authenticated: true,
252:       mode,
253:       model: reportedModel ? `${reportedModel.providerID}/${reportedModel.id}` : null,
254:       modelAvailable,
255:       limitation: versionCompatible
256:         ? modelAvailable
257:           ? null
258:           : "OpenCode reported no available model in the native catalog."
259:         : `OpenCode ${server.version} is not compatible with this build; version ${REQUIRED_OPENCODE_MAJOR}.x is required.`,
260:     });
261:   } catch (error) {
262:     const sanitized = sanitizeNetworkError(error);
263:     const auth = /401|unauthori[sz]ed|authentication|invalid credentials|forbidden/i.test(sanitized);
264:     const version = /version|incompatible|404|not found/i.test(sanitized);
265:     return nativeEngineStatusSchema.parse({
266:       available: false,
267:       serverVersion: null,
268:       versionCompatible: !version,
269:       authenticated: !auth,
270:       mode,
271:       model: null,
272:       modelAvailable: false,
273:       limitation: error instanceof NetworkPolicyError
274:         ? sanitized
275:         : auth
276:           ? "OpenCode rejected the configured credentials."
277:           : version
278:             ? "OpenCode did not expose a compatible server contract."
279:             : sanitized || "Native OpenCode is unavailable.",
280:     });
281:   }
282: }
283: 
284: /**
285:  * Checks reachability, version, and authentication before a native call.
286:  * Model availability is checked by the selected-model path in the connection
287:  * service; this function refuses a paid fallback only through that path.
288:  */
289: export async function assertEngineReady(options: NativeClientOptions): Promise<NativeEngineStatus> {
290:   const status = await probeNativeEngine(options);
291:   if (!status.available) {
292:     if (!status.authenticated) throw engineError("ENGINE_AUTH", "OpenCode authentication is not ready. Check OPENCODE_PASSWORD and start the server again.", false);
293:     if (!status.versionCompatible) throw engineError("ENGINE_INCOMPATIBLE", "The OpenCode server version is not compatible with this build.", false);
294:     throw engineError("ENGINE_UNAVAILABLE", status.limitation ?? "OpenCode is unavailable.", true);
295:   }
296:   if (!status.versionCompatible) throw engineError("ENGINE_INCOMPATIBLE", status.limitation ?? "OpenCode version is incompatible.", false);
297:   return status;
298: }

