135:     return { compatible: false, major: null, warning: "The server did not report a parseable semantic version." };
136:   }
137:   const major = Number(match[1]);
138:   if (major !== SUPPORTED_OPENCODE_MAJOR) {
139:     return {
140:       compatible: false,
141:       major,
142:       warning: `OpenCode server ${version} is outside the tested major version ${SUPPORTED_OPENCODE_MAJOR}.`,
143:     };
144:   }
145:   if (version.trim() !== TESTED_OPENCODE_VERSION) {
146:     return {
147:       compatible: true,
148:       major,
149:       warning: `OpenCode server ${version} is a ${SUPPORTED_OPENCODE_MAJOR}.x release, but this build is tested against ${TESTED_OPENCODE_VERSION}. Some capability probes may be unavailable.`,
150:     };
151:   }
152:   return { compatible: true, major, warning: null };
153: }
