155: export interface ClassifiedFailure {
156:   code:
157:     | "AUTH_REQUIRED"
158:     | "ORIGIN_BLOCKED"
159:     | "UNAVAILABLE"
160:     | "TIMEOUT"
161:     | "MALFORMED"
162:     | "VERSION_INCOMPATIBLE"
163:     | "UNKNOWN";
164:   status: number | null;
165:   message: string;
166:   state: OpenCodeConnectionState;
167: }
168: 
169: function errorStatus(error: unknown): number | null {
170:   if (!error || typeof error !== "object") return null;
171:   const candidate = error as { cause?: unknown; status?: unknown; detail?: unknown };
172:   if (typeof candidate.status === "number") return candidate.status;
173:   if (candidate.cause && typeof candidate.cause === "object") {
174:     const nested = candidate.cause as { status?: unknown };
175:     if (typeof nested.status === "number") return nested.status;
176:   }
177:   if (typeof candidate.detail === "string" && /^\d{3}$/.test(candidate.detail)) return Number(candidate.detail);
178:   return null;
179: }
180: 
181: function errorTag(error: unknown): string | null {
182:   return error && typeof error === "object" && typeof (error as { _tag?: unknown })._tag === "string"
183:     ? (error as { _tag: string })._tag
184:     : null;
185: }
186: 
187: function errorMessage(error: unknown): string {
188:   if (error instanceof Error) return error.message;
189:   if (error && typeof error === "object" && typeof (error as { message?: unknown }).message === "string") {
190:     return (error as { message: string }).message;
191:   }
192:   return String(error);
193: }
194: 
195: export function classifyConnectionError(error: unknown): ClassifiedFailure {
196:   const status = errorStatus(error);
197:   const tag = errorTag(error);
198:   const raw = errorMessage(error);
199:   const message = redactSecrets(raw);
200: 
201:   if (status === 401 || tag === "UnauthorizedError" || /authentication required|unauthori[sz]ed|password/i.test(message)) {
202:     return { code: "AUTH_REQUIRED", status: status ?? 401, message, state: "authentication_required" };
203:   }
204:   if (status === 403 || /origin|cors|forbidden|not allowed/i.test(message)) {
205:     return { code: "ORIGIN_BLOCKED", status: status ?? 403, message, state: "unavailable" };
206:   }
207:   if (/ECONNREFUSED|ENOTFOUND|EAI_AGAIN|fetch failed|network|socket|connect/i.test(message)) {
208:     return { code: "UNAVAILABLE", status, message, state: "unavailable" };
209:   }
210:   if (/timed out|timeout|aborted|AbortError/i.test(message)) {
211:     return { code: "TIMEOUT", status, message, state: "unavailable" };
212:   }
213:   if (/malformed|unexpected content|parse|decode/i.test(message)) {
214:     return { code: "MALFORMED", status, message, state: "unavailable" };
215:   }
216:   return { code: "UNKNOWN", status, message, state: "unavailable" };
217: }
218: 
219: const secretPatterns: Array<[RegExp, string]> = [
220:   [/(authorization\s*[:=]\s*)(basic|bearer)?\s*[^\s,;]+/gi, "$1[redacted]"],
221:   [/((?:password|api[_-]?key|access[_-]?token|secret|OPENCODE_PASSWORD|OPENCODE_API_KEY)\s*[:=]\s*)[^\s,;]+/gi, "$1[redacted]"],
222:   [/(https?:\/\/)([^/@\s]+)@/gi, "$1[redacted]@"],
223:   [/(Basic|Bearer)\s+[A-Za-z0-9+/=._-]{8,}/g, "$1 [redacted]"],
224: ];
225: 
226: /** Removes credential-shaped values from anything that may be logged or returned. */
227: export function redactSecrets(value: string): string {
228:   let redacted = value;
229:   for (const [pattern, replacement] of secretPatterns) redacted = redacted.replace(pattern, replacement);
230:   return redacted;
231: }
