233: export async function probeNativeEngine(options: NativeClientOptions): Promise<NativeEngineStatus> {
234:   const mode = options.mode ?? "local";
235:   try {
236:     const url = validateBaseUrlSyntax(options.baseUrl);
237:     await assertAllowedUrl(url, networkPolicy(options));
238:     const client = createNativeClient(options);
239:     const [server, models] = await Promise.all([
240:       client.server.info(),
241:       client.model.list(),
242:     ]);
243:     const versionCompatible = new RegExp(`^${REQUIRED_OPENCODE_MAJOR}\\.`).test(server.version);
244:     const reportedModel = models.data.find((model) => model.enabled !== false) ?? null;
245:     const modelAvailable = reportedModel !== null;
246: 
247:     return nativeEngineStatusSchema.parse({
248:       available: true,
249:       serverVersion: server.version,
250:       versionCompatible,
251:       authenticated: true,
252:       mode,
253:       model: reportedModel ? `${reportedModel.providerID}/${reportedModel.id}` : null,
254:       modelAvailable,
255:       limitation: versionCompatible
256:         ? modelAvailable
257:           ? null
258:           : "OpenCode reported no available model in the native catalog."
259:         : `OpenCode ${server.version} is not compatible with this build; version ${REQUIRED_OPENCODE_MAJOR}.x is required.`,
260:     });
261:   } catch (error) {
262:     const sanitized = sanitizeNetworkError(error);
263:     const auth = /401|unauthori[sz]ed|authentication|invalid credentials|forbidden/i.test(sanitized);
264:     const version = /version|incompatible|404|not found/i.test(sanitized);
265:     return nativeEngineStatusSchema.parse({
266:       available: false,
267:       serverVersion: null,
268:       versionCompatible: !version,
269:       authenticated: !auth,
270:       mode,
271:       model: null,
272:       modelAvailable: false,
273:       limitation: error instanceof NetworkPolicyError
274:         ? sanitized
275:         : auth
276:           ? "OpenCode rejected the configured credentials."
277:           : version
278:             ? "OpenCode did not expose a compatible server contract."
279:             : sanitized || "Native OpenCode is unavailable.",
280:     });
281:   }
282: }
283: 
284: /**
285:  * Checks reachability, version, and authentication before a native call.
286:  * Model availability is checked by the selected-model path in the connection
287:  * service; this function refuses a paid fallback only through that path.
288:  */
289: export async function assertEngineReady(options: NativeClientOptions): Promise<NativeEngineStatus> {
290:   const status = await probeNativeEngine(options);
291:   if (!status.available) {
292:     if (!status.authenticated) throw engineError("ENGINE_AUTH", "OpenCode authentication is not ready. Check OPENCODE_PASSWORD and start the server again.", false);
293:     if (!status.versionCompatible) throw engineError("ENGINE_INCOMPATIBLE", "The OpenCode server version is not compatible with this build.", false);
294:     throw engineError("ENGINE_UNAVAILABLE", status.limitation ?? "OpenCode is unavailable.", true);
295:   }
296:   if (!status.versionCompatible) throw engineError("ENGINE_INCOMPATIBLE", status.limitation ?? "OpenCode version is incompatible.", false);
297:   return status;
298: }

