98:   private async execute(input: MakerRunInput, active: ActiveRun): Promise<void> {
99:     const startedAt = new Date().toISOString();
100:     await this.update(input, "start", (project) => {
101:       const next = structuredClone(project);
102:       const operation = next.operations.find((item) => item.id === input.operationId);
103:       if (operation && operation.status === "QUEUED") {
104:         operation.status = "RUNNING";
105:         operation.startedAt ??= startedAt;
106:         operation.result = `Running in OpenCode with ${modelLabel(input.model)}.`;
107:       }
108:       return refreshNextAction(next);
109:     });
110: 
111:     try {
112:       const performed = await this.options.guide.perform({
113:         role: "maker",
114:         conversationId: input.projectId,
115:         sessionId: input.sessionId,
116:         prompt: input.prompt,
117:         workspace: input.workspace,
118:         model: input.model,
119:         agent: input.agent,
120:         budget: input.budget,
121:         onSession: (sessionId) => {
122:           active.sessionId = sessionId;
123:           void this.update(input, "session", (project) => {
124:             const next = structuredClone(project);
125:             const operation = next.operations.find((item) => item.id === input.operationId);
126:             if (operation) {
127:               operation.nativeSessionId = sessionId;
128:               operation.result = `Running in OpenCode session ${sessionId}.`;
129:             }
130:             rememberSession(next, "maker", sessionId);
131:             return refreshNextAction(next);
132:           }).catch(() => {
133:             // The completion update retries against the latest revision. A
134:             // failed intermediate write is recoverable and never repeats work.
135:           });
136:         },
137:       });
138:       active.sessionId = performed.sessionId;
139: 
140:       if (active.cancelled) {
141:         await this.finish(input.operationId, {
142:           status: "CANCELLED",
143:           result: "Cancellation was recorded before the native run finished.",
144:           model: input.model,
145:           agent: input.agent,
146:           sessionId: performed.sessionId,
147:           diff: performed.diff,
148:           check: null,
149:           messageId: performed.messageId,
150:           providerError: null,
151:         });
152:         return;
153:       }
154: 
155:       if (performed.pendingPermission) {
156:         await this.finish(input.operationId, {
157:           status: "WAITING_PERMISSION",
158:           result: "A native permission request is pending. Resolve it in OpenCode, then reconcile. The run was not repeated.",
159:           model: input.model,
160:           agent: input.agent,
161:           sessionId: performed.sessionId,
162:           diff: performed.diff,
163:           check: null,
164:           messageId: performed.messageId,
165:           providerError: null,
166:         });
167:         return;
168:       }
169: 
170:       const nativeFailed = performed.outcome === "failed" || performed.outcome === "interrupted";
171:       const stillRunning = performed.timedOut || performed.outcome === "running" || performed.outcome === "unknown";
172:       if (stillRunning) {
173:         await this.finish(input.operationId, {
174:           status: "ABANDONED",
175:           result: "The native Maker run did not become idle before the deadline. It was not repeated; reconcile before another run.",
176:           model: input.model,
177:           agent: input.agent,
178:           sessionId: performed.sessionId,
179:           diff: performed.diff,
180:           check: null,
181:           messageId: performed.messageId,
182:           providerError: null,
183:         });
184:         return;
185:       }
186: 
187:       const edited = !nativeFailed && !performed.diff.includes("without a file diff");
188:       const check = edited
189:         ? await traceToolOperation("maker", input.projectId, input.model, "node.test", () =>
190:           runApprovedNodeCheck(this.options.demoWorkspace, this.options.nodeCheckTimeoutMs ?? 30_000))
191:         : null;
192:       await this.finish(input.operationId, {
193:         status: edited ? "SUCCEEDED" : "FAILED",
194:         result: performed.diff,
195:         model: input.model,
196:         agent: input.agent,
197:         sessionId: performed.sessionId,
198:         diff: performed.diff,
199:         check,
200:         messageId: performed.messageId,
201:         providerError: null,
202:       });
203:     } catch (error) {
204:       const message = error instanceof Error ? error.message : "The native Maker run failed.";
205:       const errorSessionId = typeof (error as { nativeSessionId?: unknown })?.nativeSessionId === "string"
206:         ? (error as { nativeSessionId: string }).nativeSessionId
207:         : null;
208:       const providerFailure = providerErrorFor(error, input.model.providerID, errorSessionId ?? active.sessionId);
209:       const safeMessage = providerFailure?.whatHappened ?? message;
210:       await this.finish(input.operationId, {
211:         status: active.cancelled ? "CANCELLED" : failureIsUncertain(message, error) ? "ABANDONED" : "FAILED",
212:         result: active.cancelled
213:           ? "Cancellation was recorded before the native run finished."
214:           : failureIsUncertain(message, error)
215:             ? `Disconnected or interrupted: ${safeMessage}. Reconcile the native session before another run.`
216:             : safeMessage,
217:         model: input.model,
218:         agent: input.agent,
219:         sessionId: errorSessionId ?? active.sessionId,
220:         diff: null,
221:         check: null,
222:         providerError: providerFailure,
223:       });
224:     }
225:   }
