131:   const costLimits = [budgets.maxSessionCostUsd, requested?.maxCostUsd]
132:     .filter((value): value is number => typeof value === "number");
133:   const costLimit = costLimits.length ? Math.min(...costLimits) : null;
134:   if (costLimit !== null && info.cost > costLimit) {
