152:     const context = await this.modelContext(project);
153:     const startedAt = new Date().toISOString();
154:     const queued = await this.workflow.execute(actionId, payload, expectedRevision, (current) => {
155:       const next = structuredClone(current);
156:       next.engine = {
157:         model: context.model,
158:         source: context.source === "selected"
159:           ? current.engine.source
160:           : context.source === "legacy"
161:             ? "migrated-legacy"
162:             : context.source === "auto-discovery"
163:               ? "auto-discovery"
164:               : current.engine.source,
165:         updatedAt: startedAt,
166:         legacyModel: current.engine.legacyModel,
167:       };
168:       next.operations.push({
169:         id: randomUUID(),
170:         kind: "maker",
171:         payloadHash: payloadHash(payload),
172:         nativeSessionId: null,
173:         nativeMessageId: null,
174:         status: "QUEUED",
175:         result: `Queued for OpenCode with ${context.model.providerID}/${context.model.id}${context.model.variant ? `#${context.model.variant}` : ""}.`,
176:         model: context.model,
177:         agent: context.roleAgents.maker,
178:         startedAt,
179:         finishedAt: null,
180:         statusReason: null,
181:         lastObservedAt: null,
182:         appliedAt: null,
183:         providerError: null,
184:       });
185:       rememberTranscript(next, "user", this.redactPrompt(`Queued a Maker run with ${context.model.providerID}/${context.model.id}${context.model.variant ? `#${context.model.variant}` : ""}.`));
186:       return refreshNextAction(next);
187:     });
188:     const operation = queued.project.operations.at(-1);
189:     if (!operation) throw new ExperienceFailure("The Maker run was not recorded.", "RUN_NOT_RECORDED", 500, true);
190:     try {
191:       const prompt = await this.instructions("maker", queued.project, makerScope, context.model);
192:       this.runs.start({
193:         operationId: operation.id,
194:         projectId: queued.project.id,
195:         actionId,
196:         payload,
197:         sessionId: sessionFor(queued.project, "maker"),
198:         prompt,
199:         workspace: this.options.demoWorkspace,
200:         model: context.model,
201:         agent: context.roleAgents.maker,
202:         budget: queued.project.modelPreferences.budget,
203:       });
204:     } catch (error) {
205:       await this.runs.markFailed(operation.id, error, context.model, context.roleAgents.maker);
206:       throw error instanceof ExperienceFailure
207:         ? error
208:         : new ExperienceFailure(error instanceof Error ? this.redact(error.message) : "The Maker run could not start.", "RUN_START_FAILED", 500, true, operation.id);
209:     }
210:     return { project: queued.project, duplicate: false, accepted: true, operation };
211:   }
