213:   async cancel(actionId: string, expectedRevision: number, operationId: string) {
214:     void expectedRevision;
215:     const active = this.runs.active(operationId);
216:     if (!active) {
217:       const project = (await this.store.load()).state;
218:       const operation = project.operations.find((item) => item.id === operationId);
219:       if (!operation) throw new WorkflowConflict("That operation is not in this project.");
220:       if (["SUCCEEDED", "FAILED", "CANCELLED", "COMPLETED_UNAPPLIED", "ABANDONED"].includes(operation.status)) {
221:         throw new WorkflowConflict("A finished or abandoned operation cannot be cancelled. Reconcile an abandoned operation instead.");
222:       }
223:       throw new ExperienceFailure("The in-process runner is no longer present. Reconcile the native session before taking another action.", "RUN_NOT_ACTIVE", 409, false, operationId);
224:     }
225:     let interrupted = false;
226:     if (active.sessionId && this.guide.interrupt) {
227:       try {
228:         interrupted = await this.guide.interrupt(active.sessionId);
229:       } catch (error) {
230:         throw new ExperienceFailure(
231:           `The native session could not be interrupted, so it was not marked cancelled: ${this.redact(error instanceof Error ? error.message : "unknown error")}`,
232:           "CANCEL_UNAVAILABLE",
233:           503,
234:           false,
235:           operationId,
236:         );
237:       }
238:     }
239:     this.runs.markCancelled(operationId);
240:     return this.workflow.executeLatest(actionId, { operationId, intent: "cancel" }, (project) => {
241:       const next = structuredClone(project);
242:       const operation = next.operations.find((item) => item.id === operationId);
243:       if (!operation) throw new WorkflowConflict("That operation is not in this project.");
244:       if (["SUCCEEDED", "FAILED", "CANCELLED"].includes(operation.status)) {
245:         if (operation.status === "CANCELLED") return next;
246:         throw new WorkflowConflict("A finished operation cannot be cancelled.");
247:       }
248:       operation.status = "CANCELLED";
249:       operation.finishedAt = new Date().toISOString();
250:       operation.lastObservedAt = operation.finishedAt;
251:       operation.statusReason = "user-cancelled";
252:       operation.result = interrupted
253:         ? "Interrupted the native OpenCode session; the run was cancelled."
254:         : "Cancellation recorded. The native session was already idle or did not report an active request.";
255:       rememberTranscript(next, "system", operation.result);
256:       return refreshNextAction(next);
257:     });
258:   }
