501:   private async modelContext(project: Project): Promise<ModelContext> {
502:     if (!this.options.engine) {
503:       return {
504:         model: project.engine.model ?? legacyModel,
505:         source: "none",
506:         roleAgents: { oracle: null, architect: null, maker: null, witness: null },
507:       };
508:     }
509:     let discovery: OpenCodeDiscovery;
510:     try {
511:       discovery = await this.options.engine.discovery({
512:         selected: project.engine.model,
513:         accessMode: project.modelPreferences.access.mode,
514:       });
515:     } catch (error) {
516:       throw new ExperienceFailure(
517:         `OpenCode discovery is unavailable: ${this.redact(error instanceof Error ? error.message : "unknown error")}`,
518:         "OPENCODE_UNAVAILABLE",
519:         503,
520:         true,
521:       );
522:     }
523:     const reportedSelection = project.engine.model
524:       ? discovery.models.find((model) => model.providerID === project.engine.model?.providerID && model.id === project.engine.model?.id)
525:       : null;
526:     if (reportedSelection
527:       && project.modelPreferences.access.mode === "FREE_OR_LOCAL_ONLY"
528:       && reportedSelection.pricing !== "free"
529:       && reportedSelection.local !== true) {
530:       throw new ExperienceFailure(
531:         "This project is set to Free and local only. Choose a free/local model or deliberately change the model access preference.",
532:         "MODEL_ACCESS_POLICY_BLOCKED",
533:         409,
534:         false,
535:       );
536:     }
537:     let resolution = project.engine.model
538:       ? await this.options.engine.resolveModel(project.engine.model, discovery, project.modelPreferences.access.mode)
539:       : null;
540:     if (project.engine.model && !resolution) {
541:       const reported = discovery.models.find((model) =>
542:         model.providerID === project.engine.model?.providerID && model.id === project.engine.model?.id);
543:       throw new ExperienceFailure(
544:         reported
545:           ? `The selected model ${project.engine.model.providerID}/${project.engine.model.id} is not available. Choose another model in the OpenCode panel.`
546:           : `The selected model ${project.engine.model.providerID}/${project.engine.model.id} is no longer reported by OpenCode. Choose another model in the OpenCode panel.`,
547:         "MODEL_UNAVAILABLE",
548:         409,
549:         false,
550:       );
551:     }
552:     if (!resolution) {
553:       if (project.engine.legacyModel) {
554:         resolution = await this.options.engine.chooseDefaultModel(project.engine.legacyModel);
555:       }
556:       if (!resolution) {
557:         throw new ExperienceFailure(
558:           "Choose a model reported by OpenCode before starting a run.",
559:           "MODEL_SELECTION_REQUIRED",
560:           409,
561:           false,
562:         );
563:       }
564:     }
565:     if (project.engine.model?.variant) {
566:       this.options.engine.validateSelection(discovery, project.engine.model, project.modelPreferences.access.mode);
567:     }
568:     if (resolution.model.local !== true
569:       && resolution.model.pricing !== "free"
570:       && !project.modelPreferences.access.paidOrUnknownAcceptedAt) {
571:       throw new ExperienceFailure(
572:         resolution.model.pricing === "paid"
573:           ? "Confirm the paid-model policy in OpenCode settings before the first request. No provider request was made."
574:           : "Confirm the unknown-price policy in OpenCode settings before the first request. No provider request was made.",
575:         "MODEL_COST_CONFIRMATION_REQUIRED",
576:         409,
577:         false,
578:       );
579:     }
580:     const roleAgents = Object.fromEntries(
581:       discovery.roles.map((role) => [role.role, role.available ? role.agent : null]),
582:     ) as Record<"oracle" | "architect" | "maker" | "witness", string | null>;
583:     return {
584:       model: { providerID: resolution.model.providerID, id: resolution.model.id, variant: project.engine.model?.variant ?? null },
585:       source: resolution.source,
586:       roleAgents,
587:     };
588:   }
