657:         payloadHash: payloadHash(payload),
658:         nativeSessionId,
659:         nativeMessageId: null,
660:         status: uncertain ? "ABANDONED" : "FAILED",
661:         result: message,
662:         model: project.engine.model,
663:         agent: null,
664:         startedAt: new Date().toISOString(),
665:         finishedAt: uncertain ? null : new Date().toISOString(),
666:         statusReason: uncertain ? "native-outcome-unconfirmed" : classification.code.toLowerCase(),
667:         lastObservedAt: new Date().toISOString(),
668:         appliedAt: null,
669:         providerError: providerFailure?.details ?? null,
670:       });
671:       rememberTranscript(next, "system", uncertain ? `${message} The native run was not repeated.` : message);
672:       return refreshNextAction(next);
673:     });
674:     throw new ExperienceFailure(
675:       message,
676:       uncertain ? "NATIVE_UNKNOWN" : classification.code,
677:       uncertain ? 503 : classification.status,
678:       uncertain ? false : classification.retryable,
679:       saved.project.operations.at(-1)?.id ?? null,
680:       providerFailure?.details ?? null,
681:     );
682:   }
