167: function hostnameOf(hostHeader: string): string {
168:   const value = hostHeader.trim().toLowerCase();
169:   if (value.startsWith("[")) {
170:     const end = value.indexOf("]");
171:     return end > 0 ? value.slice(1, end) : value;
172:   }
173:   return value.split(":")[0];
174: }
