42:         </div>
43:         <div className="inspector-badges">
44:           {sourceLabel ? <span className="inspector-source">{sourceLabel}</span> : null}
45:           <span className="inspector-badge">Read-only view</span>
46:         </div>
47:       </header>
48:       <p className="inspector-note">{note}</p>
49: 
50:       <div className="inspector-block">
51:         <h3>Native runs</h3>
52:         {latest.length === 0 ? (
53:           <EmptyState title="No native run yet">
54:             Maker has not started an OpenCode session. Empty is the honest state.
55:           </EmptyState>
56:         ) : (
57:           <ol className="run-list">
58:             {latest.slice(0, 6).map((operation) => (
59:               <li key={operation.id} className="run-row" data-status={operation.status}>
60:                 <div className="run-row-head">
61:                   <span className="meta">{operation.kind}</span>
62:                   <StatusChip status={operation.status} />
63:                 </div>
64:                 <p className="run-result">{operation.result ?? "No native result recorded."}</p>
65:                 <p className="run-session meta">
66:                   {operation.nativeSessionId ? `Native session ${trimSession(operation.nativeSessionId)}` : "No native session reference"}
67:                   {operation.model ? ` · ${operation.model.providerID}/${operation.model.id}${operation.model.variant ? `#${operation.model.variant}` : ""}` : ""}
68:                 </p>
69:                 {operation.providerError ? (
70:                   <p className="run-provider-error">
71:                     <strong>{operation.providerError.category.replaceAll("_", " ")}</strong>
72:                     {" · "}
73:                     {operation.providerError.savedWorkChanged === "no" ? "Saved work unchanged." : "Saved work may have changed."}
74:                     {" "}
