103:                   <span className="evidence-check">{item.checkId}</span>
104:                   <StatusChip status={item.result} />
105:                 </div>
106:                 <p className="run-result">{item.result === "PASS" ? "Observed passing result." : item.limitation ?? "No limitation recorded."}</p>
107:                 {item.limitation && item.result === "PASS" ? <p className="run-limitation">{item.limitation}</p> : null}
108:                 {item.model ? <p className="run-session meta">Model {item.model.providerID}/{item.model.id}{item.model.variant ? `#${item.model.variant}` : ""}</p> : null}
109:               </li>
110:             ))}
111:           </ul>
112:         )}
113:       </div>
114: 
115:       <div className="inspector-block">
116:         <h3>Permissions and capability boundary</h3>
