118:           <p className="meta">No capability metadata is available.</p>
119:         ) : (
120:           <ul className="permission-list">
121:             {capabilities.map((capability) => (
122:               <li key={capability.id}>
123:                 <span className="permission-name">{capability.purpose}</span>
124:                 <span className="permission-detail">{capability.permission}</span>
125:               </li>
126:             ))}
127:           </ul>
128:         )}
129:         <p className="inspector-footnote">
130:           Workflow approval is not tool permission. OpenCode remains the authority for native tool decisions.
131:         </p>
132:       </div>
133:     </section>
134:   );
135: }
