148:       const temporaryPath = `${this.path}.tmp-${process.pid}-${randomUUID()}`;
149:       try {
150:         await writePrivateFile(temporaryPath, `${JSON.stringify(next, null, 2)}\n`);
151:         await rename(temporaryPath, this.path);
152:         await this.syncDirectory(dirname(this.path));
153:       } catch (error) {
154:         await unlink(temporaryPath).catch(() => undefined);
155:         throw error;
156:       }
157:       await this.pruneRetainedFiles();
158:       return next;
159:     } catch (error) {
160:       throw this.mapWriteError(error);
161:     } finally {
162:       if (release) await release();
163:     }
164:   }
