166:   private async readNoFollow(path: string): Promise<Buffer> {
167:     const handle = await open(path, constants.O_RDONLY | constants.O_NOFOLLOW);
168:     try {
169:       const info = await handle.stat();
170:       if (!info.isFile()) {
171:         throw new StateError("STATE_UNSAFE", "The project state path is not a regular file.");
172:       }
173:       return await handle.readFile();
174:     } finally {
175:       await handle.close();
176:     }
177:   }
178: 
179:   private async readProject(path: string): Promise<{ state: Project; migrated: boolean; fromVersion: number }> {
180:     let raw: string;
181:     try {
182:       raw = (await this.readNoFollow(path)).toString("utf8");
183:     } catch (error) {
184:       if ((error as NodeJS.ErrnoException).code === "ELOOP") {
185:         throw new StateError("STATE_UNSAFE", "The project state file is a symbolic link. It was not followed.");
186:       }
187:       throw error;
188:     }
189:     const parsed = JSON.parse(raw) as unknown;
190:     const migration = migrateProject(parsed);
191:     return { state: migration.project, migrated: migration.migrated, fromVersion: migration.fromVersion };
192:   }
193: 
194:   private async backupCurrent(revision: number): Promise<void> {
195:     await ensurePrivateDirectory(this.backupDirectory);
196:     const stamp = this.options.now().toISOString().replace(/[:.]/g, "-");
197:     const backupPath = join(this.backupDirectory, `project-r${revision}-${stamp}.json`);
198:     const snapshot = await this.readNoFollow(this.path);
199:     const temporary = `${this.previousPath}.tmp-${randomUUID()}`;
200:     await writePrivateBytes(temporary, snapshot);
201:     await rename(temporary, this.previousPath);
202:     await writePrivateBytes(backupPath, snapshot);
203:   }
204: 
205:   private async quarantineCorrupt(): Promise<string> {
206:     const stamp = this.options.now().toISOString().replace(/[:.]/g, "-");
207:     const target = join(dirname(this.path), `${basename(this.path)}.corrupt-${stamp}-${randomUUID().slice(0, 8)}`);
208:     const corrupt = await this.readNoFollow(this.path);
209:     await writePrivateBytes(target, corrupt);
210:     await this.pruneRetainedFiles().catch(() => undefined);
211:     return target;
212:   }
