214:   private async acquireLock(): Promise<() => Promise<void>> {
215:     const started = Date.now();
216:     while (true) {
217:       try {
218:         const handle = await open(this.lockPath, constants.O_WRONLY | constants.O_CREAT | constants.O_EXCL, 0o600);
219:         await handle.writeFile(JSON.stringify({ pid: process.pid, createdAt: new Date().toISOString() }));
220:         await handle.close();
221:         return async () => {
222:           await unlink(this.lockPath).catch(() => undefined);
223:         };
224:       } catch (error) {
225:         if ((error as NodeJS.ErrnoException).code !== "EEXIST") throw error;
226:         if (await this.staleLock()) {
227:           await unlink(this.lockPath).catch(() => undefined);
228:           continue;
229:         }
230:         if (Date.now() - started >= this.options.lockTimeoutMs) {
231:           throw new StateError("STATE_BUSY", "Another process is writing project state. Try again shortly.", 503, true);
232:         }
233:         await new Promise((resolveDelay) => setTimeout(resolveDelay, 50));
234:       }
235:     }
236:   }
237: 
238:   private async staleLock(): Promise<boolean> {
239:     try {
240:       const info = await stat(this.lockPath);
241:       return Date.now() - info.mtimeMs > 30_000;
242:     } catch {
243:       return true;
244:     }
245:   }
246: 
247:   private async syncDirectory(path: string): Promise<void> {
248:     try {
249:       const handle = await open(path, constants.O_RDONLY);
250:       try {
251:         await handle.sync();
252:       } finally {
253:         await handle.close();
254:       }
255:     } catch {
256:       // Directory fsync is best effort on filesystems that do not support it.
257:     }
258:   }
259: 
260:   private async pruneRetainedFiles(): Promise<void> {
261:     await this.pruneDirectory(this.backupDirectory, /^project-.*\.json$/, this.options.backups);
262:     const directory = dirname(this.path);
263:     const prefix = `${basename(this.path)}.corrupt-`;
264:     await this.pruneDirectory(directory, new RegExp(`^${prefix.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")}`), this.options.corruptFiles);
265:   }
266: 
267:   private async pruneDirectory(directory: string, pattern: RegExp, keep: number): Promise<void> {
268:     let entries: string[];
269:     try {
270:       entries = await readdir(directory);
271:     } catch {
272:       return;
273:     }
274:     const candidates: Array<{ name: string; time: number }> = [];
275:     for (const name of entries) {
276:       if (!pattern.test(name)) continue;
277:       try {
278:         const info = await stat(join(directory, name));
279:         candidates.push({ name, time: info.mtimeMs });
280:       } catch {
281:         // The file disappeared between readdir and stat.
282:       }
283:     }
284:     candidates.sort((left, right) => right.time - left.time);
285:     const maxAge = this.options.backupMaxAgeDays * 24 * 60 * 60 * 1000;
286:     for (const [index, candidate] of candidates.entries()) {
287:       const expired = Date.now() - candidate.time > maxAge;
288:       if (index < keep && !expired) continue;
289:       await unlink(join(directory, candidate.name)).catch(() => undefined);
290:     }
291:   }
292: 
293:   private mapWriteError(error: unknown): Error {
294:     if (error instanceof StateError || error instanceof RevisionConflict) return error;
295:     const code = (error as NodeJS.ErrnoException).code;
296:     if (code === "ENOSPC" || code === "EDQUOT") {
297:       return new StateError("STATE_DISK_FULL", "The data disk is full. Project state was not replaced.", 507, true);
298:     }
299:     if (code === "EACCES" || code === "EPERM" || code === "EROFS") {
300:       return new StateError("STATE_READ_ONLY", "The data directory is read-only. Project state was not replaced.", 503, false);
301:     }
302:     if (code === "ENOTDIR" || code === "EEXIST" || code === "EISDIR") {
303:       return new StateError("STATE_WRITE_FAILED", "The data path is not a writable directory. Project state was not replaced.", 503, false);
304:     }
305:     if (error instanceof Error && /project state|regular file|symbolic link/i.test(error.message)) {
306:       return new StateError("STATE_WRITE_FAILED", error.message, 503, false);
307:     }
308:     return new StateError("STATE_WRITE_FAILED", "Project state could not be written atomically. The previous snapshot remains intact.", 503, true);
309:   }
310: }

