export function markRecovered(
  project: Project,
  operationId: string,
  outcome: {
    status: "SUCCEEDED" | "FAILED" | "COMPLETED_UNAPPLIED" | "RUNNING";
    result: string;
    sessionId: string | null;
    messageId: string | null;
    diff: string | null;
    check: RecoveredMakerOutcome["check"];
    model: ModelRef | null;
    providerError?: ProviderErrorDetails | null;
    statusReason?: string | null;
    phase?: OperationPhase | null;
  },
): Project {
  const next = structuredClone(project);
  const operation = next.operations.find((item) => item.id === operationId);
  if (!operation) return refreshNextAction(next);
  if (operation.appliedAt) {
    // A recovered result is applied exactly once; replays keep the record.
    return refreshNextAction(next);
  }
  if (outcome.status === "SUCCEEDED") {
    if (!outcome.check) throw new Error("A recovered Maker success records a validated check result.");
    operation.status = "SUCCEEDED";
    operation.finishedAt ??= new Date().toISOString();
    operation.appliedAt = new Date().toISOString();
    operation.lastObservedAt = operation.appliedAt;
    operation.nativeSessionId = outcome.sessionId ?? operation.nativeSessionId;
    operation.nativeMessageId = outcome.messageId ?? operation.nativeMessageId;
    operation.statusReason = null;
    operation.providerError = null;
    const checkText = `Node check exit ${outcome.check.code ?? "unavailable"}. ${outcome.check.output}`;
    operation.result = `${outcome.result}\n${checkText}`;
    operation.progress = null;
    if (outcome.model) operation.model = outcome.model;
    if (outcome.sessionId) rememberSession(next, "maker", outcome.sessionId);
    next.evidence.push({
      id: randomUUID(),
      checkId: "CK-06",
      nativeResultReference: outcome.sessionId ?? "native-session-unavailable",
      testedFingerprint: payloadHash(outcome.check.output),
      result: outcome.check.code === 0 ? "PASS" : "FAIL",
      observedAt: new Date().toISOString(),
      limitation: outcome.check.code === 0 ? null : "The native edit did not leave a passing Node test.",
      model: operation.model,
    });
    const capability = next.capabilities.find((item) => item.id === "node-check");
    if (capability) {
      capability.availability = "available";
      capability.observedOutcome = outcome.check.code === 0 ? "PASS" : "FAIL";
    }
    const inspection = next.capabilities.find((item) => item.id === "inspect-changes");
    if (inspection) {
      inspection.availability = "available";
      inspection.observedOutcome = outcome.diff;
    }
    rememberTranscript(
      next,
      "maker",
      `Reconciled a late native result: ${outcome.diff ?? outcome.result} (${modelLabel(outcome.model ?? { providerID: "opencode", id: "unknown", variant: null })})`,
    );
  } else {
    operation.status = outcome.status;
    operation.lastObservedAt = new Date().toISOString();
    operation.statusReason = outcome.statusReason
      ?? (outcome.status === "FAILED" ? "native-failure-confirmed" : "native-result-not-retrieved");
    operation.result = outcome.result;
    operation.progress = outcome.phase
      ? markProgressValue(operation.progress, outcome.phase, PHASE_DETAIL[outcome.phase], operation.lastObservedAt)
      : markProgressValue(operation.progress, "AWAITING_RECONCILIATION", PHASE_DETAIL.AWAITING_RECONCILIATION, operation.lastObservedAt);
    if (outcome.status === "FAILED") operation.finishedAt ??= new Date().toISOString();
    if (outcome.providerError) operation.providerError = outcome.providerError;
  }
  return refreshNextAction(next);
}

/** A deterministic helper kept separate so callers can seed initial progress. */
export function markProgressValue(
  progress: Project["operations"][number]["progress"],
  phase: OperationPhase,
  detail: string | null,
  now: string,
): Project["operations"][number]["progress"] {
  // Imported lazily to avoid a cycle with the module boundary below.
  return markProgressForward(progress, phase, detail, now);
}

import { setProgress as markProgressForward } from "./progress.ts";

function modelLabel-MARKER(message: string, sessionId: string): string {
  void message;
  return sessionId;
}

