  async markFailed(input: GuideRunInput, error: unknown): Promise<void> {
    const sessionId = typeof (error as { nativeSessionId?: unknown })?.nativeSessionId === "string"
      ? (error as { nativeSessionId: string }).nativeSessionId
      : this.activeRuns.get(input.operationId)?.sessionId ?? null;
    const providerFailure = providerErrorFor(error, input.model.providerID, sessionId);
    const message = providerFailure?.whatHappened ?? (error instanceof Error ? error.message : "The native run failed.");
    const uncertain = /timed out|timeout|ECONN|fetch|network|socket|unavailable|interrupted|disconnected/i.test(message)
      || Boolean(providerFailure?.retryable);
    await this.finish(input, {
      status: uncertain || providerFailure?.retryable ? "ABANDONED" : "FAILED",
      result: uncertain
        ? `${message} The native run was not repeated. Reconcile the native session to recover it.`
        : message,
      statusReason: uncertain ? "native-outcome-unconfirmed" : "run-failed",
      sessionId,
      messageId: null,
      providerError: providerFailure,
      transcript: `${message} The run was not repeated automatically.`,
    });
  }

