          status: "FAILED",
          result: parsed.resultText,
          statusReason: "malformed-response",
          sessionId: spoken.sessionId,
          messageId: spoken.messageId,
          providerError: null,
          transcript: parsed.resultText;
        });
        return;
      }
      await stage("APPLYING_RESULT");
      const applied = await this.applyReply(input, parsed);
      rememberTranscript;
      await this.finish(input, {
        status: "SUCCEEDED",
        result: applied.resultText,
        statusReason: null,
        sessionId: spoken.sessionId,
        messageId: spoken.messageId,
        providerError: null,
        transcript: applied.transcript,
      });
    } catch (error) {
      settled = true;
      await this.markFailed(input, error);
      void observing;
    }
  }

  /**
   * Safe polling while the native call is in flight. It never surfaces raw
   * model output; it only records that output has started arriving so the
   * phase display can move past "waiting for the model".
   */
