  private async execute(input: GuideRunInput, active: { sessionId: string | null; cancelled: boolean }): Promise<void> {
    const stage = async (state: "CONNECTING" | "SESSION_CREATED" | "WAITING_FOR_MODEL" | "RECEIVING_OUTPUT" | "VALIDATING_RESULT" | "WAITING_PERMISSION" | "APPLYING_RESULT", detail?: string | null) => {
