      const spoken = await this.options.guide.speak({
        role: input.intent === "witness" ? "witness" : input.intent === "draft" ? "architect" : "oracle",
        conversationId: input.projectId,
        sessionId: input.sessionId,
        prompt: input.prompt,
        workspace: input.workspace,
        model: input.model,
        agent: input.agent,
        budget: input.budget,
        onSession: (sessionId) => {
