      operation.result = outcome.result;
      operation.progress = null;
      if (outcome.transcript) {
        rememberTranscript(
          next,
          input.intent === "witness" ? "witness" : input.intent === "draft" ? "architect" : "oracle",
          outcome.transcript.slice(0, 8_000),
        );
      }
