950:   if (error instanceof NativeTimeoutError) {
951:     return { code: "NATIVE_UNKNOWN", status: 503, retryable: false, unknown: true, message: "The native run timed out. Reconcile the native session before any new run." };
952:   }
953:   if (error instanceof NetworkPolicyError) {
954:     return { code: "NATIVE_UNKNOWN", status: 503, retryable: false, unknown: true, message: error.message };
955:   }
