const TERMINAL_STATUSES = new Set(["SUCCEEDED", "FAILED", "CANCELLED"]);

const phaseLabels: Record<string, string> = {
  CONNECTING: "connecting",
  SESSION_CREATED: "session created",
  WAITING_FOR_MODEL: "waiting for the model",
