    nativeSessionId: "ses_outstanding",
    nativeMessageId: null,
    status: "RUNNING",
    result: "Running in OpenCode with opencode/flint-40b-free.",
    model: null,
    agent: null,
    startedAt: new Date().toISOString(),
    finishedAt: null,
    statusReason: null,
    lastObservedAt: null,
    appliedAt: null,
    providerError: null,
    intent: "maker-run",
    sectionId: null,
    startingRevision: state.revision,
    idempotencyKey: "outstanding",
