  })).project;
  const before = project.sections[0].hash;
  const response = await app.request("/api/messages", {
    method: "POST",
    headers,
    body: JSON.stringify({ actionId: "draft", expectedRevision: project.revision, intent: "draft", text: "Draft the control section." }),
  });
