// Terminal operations carry the outcome in status/result; the transient
// progress marker is cleared so history stays truthful. A pending
// permission keeps its phase so the interface explains why the run is
// still blocked, and an abandoned run keeps its recovery marker so the
// native session remains reconcileable after startup recovery.
operation.progress = outcome.status === "WAITING_PERMISSION"
  ? phaseValue(operation.progress, "WAITING_PERMISSION", PHASE_DETAIL.WAITING_PERMISSION)
  : outcome.status === "ABANDONED" && operation.progress?.phase === "AWAITING_RECONCILIATION"
    ? operation.progress
    : null;

